import { Accordion, Box, HStack, Separator, Text } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import type { Utterance } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface UserMessageInfoProps {
  utterance: Utterance;
  onClose: () => void;
}

export const UserMessageInfo = ({ utterance, onClose }: UserMessageInfoProps) => {
  const getConfidencePalette = (confidence: number) =>
    confidence > 0.7 ? "green" : confidence > 0.4 ? "yellow" : "red";

  const intentPills = utterance.intents?.slice(0, 3).map((intent) => (
    <HStack key={intent.id} mb="1">
      <Box
        colorPalette={getConfidencePalette(intent.confidence)}
        px="1.5"
        py="0.5"
        borderRadius="sm"
        fontWeight="600"
      >
        {(intent.confidence * 100).toFixed(1)}%
      </Box>
      <Text>{intent.name}</Text>
    </HStack>
  ));

  return (
    <DetailView title="User message details" onClose={onClose}>
      <InfoField label="Predicted intents">
        {intentPills && intentPills.length > 0 ? <Box>{intentPills}</Box> : <Text>-</Text>}
      </InfoField>

      {utterance.commands ? (
        <InfoField label="Predicted Commands">
          <RasaCodeBlock
            code={
              utterance.commands != null ? JSON.stringify(utterance.commands, null, 2) || "-" : "—"
            }
          />
        </InfoField>
      ) : null}

      <Separator mt="2" />

      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={{ ...utterance, conversationEventType: "USER" }} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
